def solve_nqueens(n):
    cols=set()
    pos_diag=set()
    neg_diag=set()
    solution=[-1]*n
    def backtrack(r):
        if r==n:
            return True
        for c in range(n):
            if c in cols or (r+c) in pos_diag or (r-c) in neg_diag:
                continue
            cols.add(c); pos_diag.add(r+c); neg_diag.add(r-c); solution[r]=c
            if backtrack(r+1):
                return True
            cols.remove(c); pos_diag.remove(r+c); neg_diag.remove(r-c)
        return False
    if backtrack(0):
        return solution
    return None
